import { ExpenseRecord, TaxCalculationResult, UserProfile } from '../types';
import { formatCurrency, TAX_CONFIGS } from './taxRules';
import { authedFetch } from './apiBase';
import { saveFile } from '../utils/saveFile';
import { compressReceiptImage } from './receiptOcr';

/**
 * Browser-side export helpers.
 *
 * PDF, Excel and the CA zip pack are Pro features, so they are generated by the TaxVault server
 * (POST /api/exports/:kind) after it checks the signed-in user's plan. Their generators live in
 * exportService.ts, which only the server imports, so they are not in the app bundle and cannot
 * be unlocked by editing the locally stored profile. CSV and the share links stay free and local.
 */

export type ProExportKind = 'pdf' | 'xlsx' | 'zip';

export type ProExportResult =
  | { ok: true; fileName: string }
  | { ok: false; reason: 'pro_required' | 'sign_in' | 'failed'; message: string };

/** Most receipt images sent with one export request (photos are at most 100 KB each). */
export const MAX_PDF_RECEIPT_IMAGES = 60;
export const MAX_ZIP_RECEIPT_IMAGES = 400;

/**
 * A receipt image as a compact JPEG data URL for embedding in a PDF, or null if it cannot be
 * loaded. Web links (e.g. sample receipts) are downloaded here on the device, so the server
 * never fetches arbitrary URLs.
 */
async function toCompactReceiptImage(url: unknown): Promise<string | null> {
  if (typeof url !== 'string' || !url) return null;
  try {
    let dataUrl = url;
    if (/^https?:\/\//i.test(url)) {
      const res = await fetch(url);
      if (!res.ok) return null;
      const blob = await res.blob();
      if (!blob.type.startsWith('image/')) return null;
      dataUrl = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result));
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(blob);
      });
    }
    if (!dataUrl.startsWith('data:image')) return null;
    const compact = await compressReceiptImage(dataUrl);
    return /^data:image\/(jpe?g|png);base64,/i.test(compact) ? compact : null;
  } catch {
    return null;
  }
}

/** Expenses with receipt images converted for the PDF; images beyond the cap are left out. */
export async function withPdfReceiptImages(
  expenses: ExpenseRecord[],
  maxImages: number = MAX_PDF_RECEIPT_IMAGES
): Promise<ExpenseRecord[]> {
  const out = expenses.map((e) => ({ ...e }));
  let included = 0;
  const queue = out.filter((e) => typeof e.receiptUrl === 'string' && e.receiptUrl);
  for (let i = 0; i < queue.length; i += 4) {
    const batch = queue.slice(i, i + 4);
    const images = await Promise.all(batch.map((e) => (included < maxImages ? toCompactReceiptImage(e.receiptUrl) : null)));
    batch.forEach((e, j) => {
      if (images[j] && included < maxImages) {
        e.receiptUrl = images[j]!;
        included += 1;
      } else {
        delete (e as any).receiptUrl;
      }
    });
  }
  return out;
}

export const PRO_EXPORT_UPSELL = 'PDF reports, Excel registers and CA audit packs require Tax Compliance Pro.';

export class ExportClient {
  /** Downloads in a browser; in the app, opens the share sheet so the file can be saved or sent. */
  public static triggerDownload(blob: Blob, fileName: string): Promise<void> {
    return saveFile(blob, fileName);
  }

  /**
   * Asks the server to build a Pro export (PDF / Excel / CA zip pack) and downloads it.
   * The server refuses with 402 unless the signed-in user has a paid plan on record.
   */
  public static async downloadProExport(
    kind: ProExportKind,
    params: {
      profile: UserProfile;
      expenses: ExpenseRecord[];
      taxResult: TaxCalculationResult;
      fileName: string;
      options?: Record<string, unknown>;
    }
  ): Promise<ProExportResult> {
    // Receipt images go only into the zip pack, or into a PDF when the user asks for them;
    // otherwise they are left out to keep uploads small.
    // Stored photos arrive as private links, so they are fetched and inlined here when needed.
    const wantsImages = kind === 'zip' || (kind === 'pdf' && Boolean(params.options?.includeReceiptImages));
    const source = wantsImages
      ? await withPdfReceiptImages(params.expenses, kind === 'zip' ? MAX_ZIP_RECEIPT_IMAGES : MAX_PDF_RECEIPT_IMAGES)
      : params.expenses;
    const expenses = source.map((e) => {
      const { originalImage, receiptThumbnail, ...rest } = e as any;
      const keepImage = wantsImages;
      if (!keepImage || !(typeof rest.receiptUrl === 'string' && rest.receiptUrl.startsWith('data:image'))) {
        delete rest.receiptUrl;
      }
      return rest;
    });

    let res: Response;
    try {
      res = await authedFetch(`/api/exports/${kind}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          profile: params.profile,
          expenses,
          taxResult: params.taxResult,
          options: params.options || {},
        }),
      });
    } catch {
      return { ok: false, reason: 'failed', message: 'Could not reach the TaxVault server. Check your connection and try again.' };
    }

    if (res.status === 401) {
      return { ok: false, reason: 'sign_in', message: 'Sign in with your TaxVault account to download PDF and Excel reports.' };
    }
    if (res.status === 402) {
      return { ok: false, reason: 'pro_required', message: PRO_EXPORT_UPSELL };
    }
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      return { ok: false, reason: 'failed', message: body?.error || 'Failed to generate the report. Please try again.' };
    }

    await this.triggerDownload(await res.blob(), params.fileName);
    return { ok: true, fileName: params.fileName };
  }

  /**
   * One-stop helper to download CSV safely (free on every plan)
   */
  public static downloadCSV(expenses: ExpenseRecord[], fileName?: string): Promise<void> {
    const blob = this.generateCSV(expenses);
    const safeName = fileName || `TaxVault_Expenses_${new Date().toISOString().split('T')[0]}.csv`;
    return this.triggerDownload(blob, safeName);
  }

  public static generateCSV(expenses: any) {
    const headers = 'ID,Date,Merchant,Category,Amount,Tax,BusinessPercentage\n';
    const rows = expenses.map((e: any) => {
      const taxAmt = (Number(e.cgst) || 0) + (Number(e.sgst) || 0) + (Number(e.igst) || 0) || Number(e.taxAmount) || Number(e.gstAmount) || Number(e.salesTaxAmount) || 0;
      return `"${e.id || ''}","${e.date || ''}","${(e.merchant || '').replace(/"/g, '""')}","${e.category || ''}",${Number(e.amount) || 0},${taxAmt},${e.businessPercentage ?? 100}`;
    }).join('\n');
    return new Blob([headers + rows], { type: 'text/csv' });
  }

  /**
   * Generates WhatsApp share URL with prefilled text
   */
  public static getWhatsAppShareUrl(
    profile: UserProfile,
    taxResult: TaxCalculationResult,
    phone?: string
  ): string {
    const targetPhone = (phone || profile?.accountantPhone || '').replace(/[^0-9]/g, '');
    const country = profile?.country || 'NZ';
    const config = TAX_CONFIGS[country] || TAX_CONFIGS['NZ'];
    const curr = profile?.defaultCurrency || config.currencyCode;
    const sym = profile?.currencySymbol || config.currencySymbol;
    const fmt = (val: number) => formatCurrency(Number(val) || 0, curr, sym, true);
    const taxLabel = country === 'US' ? 'Sales Tax' : 'GST/HST';
    const taxIdName = country === 'NZ' ? 'IRD' : country === 'AU' ? 'ABN' : country === 'CA' ? 'CRA BN' : country === 'US' ? 'EIN' : 'GSTIN';
    const taxId = profile?.taxId || profile?.pan || profile?.gstin || 'Unregistered';

    const greeting = country === 'IN' ? 'Namaste CA Sahab,' : `Hello ${profile?.accountantName || 'Tax Advisor'},`;
    const message = `${greeting}

Here is my business expense and ${taxLabel} summary from TaxVault for ${profile?.financialYear || config.taxYearLabel}:

Client: ${profile?.businessName || profile?.fullName || 'Business Entity'}
${taxIdName}: ${taxId}
Total Invoices: ${taxResult?.expenseCount || 0}
Total Expenses: ${fmt(taxResult?.totalExpenses || 0)}
Business Claimable: ${fmt(taxResult?.claimableBusinessTotal || 0)}
${taxLabel} Identified: ${fmt(taxResult?.totalGstIdentified || 0)}
Eligible Credit / Deduction: ${fmt(taxResult?.eligibleGstItc || 0)}

I have compiled the PDF report, Excel register, and all digitized receipts. Please let me know if any further clarification is required.`;

    const encoded = encodeURIComponent(message);
    return targetPhone
      ? `https://wa.me/${targetPhone}?text=${encoded}`
      : `https://wa.me/?text=${encoded}`;
  }

  /**
   * Generates Email mailto URL for CA / CPA / Tax Agent
   */
  public static getEmailShareUrl(
    profile: UserProfile,
    taxResult: TaxCalculationResult,
    email?: string
  ): string {
    const country = profile?.country || 'NZ';
    const config = TAX_CONFIGS[country] || TAX_CONFIGS['NZ'];
    const curr = profile?.defaultCurrency || config.currencyCode;
    const sym = profile?.currencySymbol || config.currencySymbol;
    const fmt = (val: number) => formatCurrency(Number(val) || 0, curr, sym, true);
    const taxLabel = country === 'US' ? 'Sales Tax' : 'GST/HST';

    const targetEmail = email || profile?.accountantEmail || '';
    const subject = encodeURIComponent(`TaxVault Expense & ${taxLabel} Compliance Pack - ${profile?.businessName || profile?.fullName || 'Business'} (${profile?.financialYear || config.taxYearLabel})`);
    const body = encodeURIComponent(`Dear ${profile?.accountantName || 'Tax Advisor / Accountant'},

Please find attached the compiled expense records, ${taxLabel} calculation, and audit vouchers for ${profile?.businessName || profile?.fullName || 'Business'} for ${profile?.financialYear || config.taxYearLabel}.

Key Summary Metrics:
- Total Incurred Expenses: ${fmt(taxResult?.totalExpenses || 0)}
- Allowable Business Deductions: ${fmt(taxResult?.claimableBusinessTotal || 0)}
- Total ${taxLabel} Paid: ${fmt(taxResult?.totalGstIdentified || 0)}
- Eligible Input Tax Credit / Deductions: ${fmt(taxResult?.eligibleGstItc || 0)}
- Invoices Count: ${taxResult?.expenseCount || 0}

Looking forward to your review and filing confirmation.

Regards,
${profile?.fullName || 'Taxpayer'}
${profile?.phone || ''}`);

    return `mailto:${targetEmail}?subject=${subject}&body=${body}`;
  }
}
